// Balasan sederhana — ganti node ini dengan AI Agent / OpenAI / Gemini
// Input dari Laravel: { session_id, message, history }
const pesan = ($json.body?.message ?? $json.message ?? '').toLowerCase();

let reply;
if (pesan.includes('halo') || pesan.includes('hai')) {
  reply = 'Halo dari n8n! 🤖 Workflow-mu sudah tersambung dengan benar.';
} else if (pesan.includes('jam') || pesan.includes('waktu')) {
  reply = 'Sekarang pukul ' + new Date().toLocaleTimeString('id-ID', { timeZone: 'Asia/Jakarta' }) + ' WIB.';
} else {
  reply = 'n8n menerima pesanmu: "' + ($json.body?.message ?? $json.message) + '". Ganti node Code ini dengan AI Agent untuk jawaban cerdas!';
}

return [{ json: { reply } }];
